import logging
from pathlib import Path
from tempfile import gettempdir
from .rmod_interface import RMODBuilder
from .exceptions import UnrecognizedRMODId


logger = logging.getLogger(name='rmod_serial_interface')
logger.setLevel(logging.DEBUG)
logger.addHandler(logging.NullHandler())


class RMODManager:
    def __init__(self):
        self._connection_store = {}
        self._session_logs_dir = Path(gettempdir()) / 'rsi_logs'
        self._session_logs_dir.mkdir(exist_ok=True)

    def setup_rmod_connection(self, login, password, port):
        if port in self._connection_store:
            return self._connection_store[port]['rmod'].serial_number
        logger.info(f"Requesting connection to  RMOD on port {port}")
        rmod, log_path = RMODBuilder.build(login, password, port, self._session_logs_dir)
        sn = self._initialize_rmod(rmod)
        logger.info(f"Successful initialization of rmod on port {port}; SN = {sn}, log file = {log_path}")
        self._connection_store[port] = {'rmod': rmod, 'log_path': log_path}
        return sn

    def setup_custom_rmod_connection(self, port, login, password, shell_prompt_regex=None):
        if port in self._connection_store:
            return self._connection_store[port]['rmod'].serial_number
        logger.info(f"Requesting custom (!) connection to RMOD on port {port}")
        rmod, log_path = RMODBuilder.build_custom(port, self._session_logs_dir,
                                                  login=login, password=password, shell_prompt_regex=shell_prompt_regex)
        sn = self._initialize_rmod(rmod)
        logger.info(f"Successful initialization of custom rmod on port {port}; SN = {sn}, log file = {log_path}")
        self._connection_store[port] = {'rmod': rmod, 'log_path': log_path}
        return sn

    @staticmethod
    def _initialize_rmod(rmod):
        rmod.connect()
        try:
            rmod.first_log_in()
            return rmod.serial_number
        except Exception:
            rmod.disconnect()
            raise

    def teardown_rmod_connection(self, port):
        logger.info(f"Initiating connection teardown on {port}...")
        self._get_connection(port)['rmod'].disconnect()
        del self._connection_store[port]
        logger.info(f"Connection on {port} has been closed.")

    def _teardown_all(self):
        logger.info("Initiating teardown of all connections...")
        all_connections = self._connection_store.copy()
        for port in all_connections:
            self.teardown_rmod_connection(port)
        logger.info("Teardown done.")

    def execute_command(self, cmd, port, elevated=False, timeout=30, wait_echo=True):
        logger.info(f"Executing command '{cmd}' on RMOD {port} ({timeout}s timeout)")
        output, timedout = self._get_connection(port)['rmod'].execute_cmd(cmd, elevated, timeout, wait_echo=wait_echo)
        if timedout:
            state = self._get_connection(port)['rmod'].get_state()
            logger.info(
                f"Command '{cmd}' on RMOD {port} timed out after {timeout} seconds; "
                f"Rmod state = {state}; Rmod output thus far: {output}"
            )
        return output

    def send_command(self, cmd, port, elevated=False, wait_echo=True):
        logger.info(f"Sending command '{cmd}' on RMOD {port}")
        self._get_connection(port)['rmod'].send_cmd(cmd, elevated=elevated, wait_echo=wait_echo)

    def take_snapshot(self, port, timeout=180):
        logger.info(f"Snapshot requested on RMOD {port}")
        path = self._get_connection(port)['rmod'].take_snapshot(timeout=timeout)
        logger.info(f"Snapshot on RMOD {port} done.")
        return path

    def collect_rmod_output(self, port):
        logger.info(f"Requested collection of output on RMOD: {port}")
        return self._get_connection(port)['rmod'].collect_output()

    def get_session_log_path(self, port):
        return self._get_connection(port)['log_path']

    def get_rmod_info(self, port):
        logger.info(f"Requested info on RMOD: {port}")
        return self._get_connection(port)['rmod'].get_state()

    def set_rmod_credentials(self, port, login, password, shell_prompt_regex=None):
        logger.info(f"Setting credentials for RMOD on port {port}")
        rmod = self._get_connection(port)['rmod']
        rmod.set_credentials(login, password)
        if shell_prompt_regex is not None:
            rmod.shell_prompt_regex = shell_prompt_regex
        logger.info(f"Credentials updated for RMOD on port {port}")

    def _get_connection(self, port):
        try:
            return self._connection_store[port]
        except KeyError:
            raise UnrecognizedRMODId(f"No active connection on port {port}")
